import { Injectable } from '@nestjs/common';
import { z } from 'zod';
import { PrismaService } from '../../prisma/prisma.service.js';
import { CatalogService } from '../catalog/catalog.service.js';
import { PaymentsService } from '../payments/payments.service.js';
import { UsageService } from '../usage/usage.service.js';

/** Cards are generated by the server, never by the language model. */
export interface AssistantCard {
  title: string;
  lines: string[];
  href: string;
  label: string;
  kind: 'plan' | 'quote' | 'account' | 'help';
}
export interface ToolResult {
  data: unknown;
  cards: AssistantCard[];
}
const text = z.string().trim().min(1).max(120);
const id = z.string().min(1).max(160);
const offset = z.number().int().min(0).max(10000);
const date = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
const args = {
  search_destinations: z.object({ query: text }).strict(),
  list_plans: z.object({ destination: text, offset }).strict(),
  quote_plan: z
    .object({
      productId: id,
      startDate: date,
      endDate: date,
      quantity: z.number().int().min(1).max(5),
      promoCode: text.nullable(),
    })
    .strict(),
  list_my_esims: z.object({ offset }).strict(),
  list_my_orders: z.object({ offset }).strict(),
  my_esim_details: z
    .object({
      esimId: id,
      detail: z.enum(['usage', 'device', 'history', 'topup_plans']),
    })
    .strict(),
  help: z
    .object({
      topic: z.enum([
        'installation',
        'compatibility',
        'payments',
        'refunds',
        'support',
        'privacy',
      ]),
    })
    .strict(),
};
export const ASSISTANT_TOOLS = Object.entries(args).map(([name, schema]) => ({
  type: 'function' as const,
  name,
  strict: true,
  description: (
    {
      search_destinations:
        'Search the store by country, region or alias, e.g. Dubai. Ask which destination when ambiguous.',
      list_plans:
        'List up to 12 store plans for a destination code from search. Retail prices are ESTIMATES, unlimited is PER DAY. Never calculate an exact total from estimates. Use quote_plan for a dated trip. offset starts at 0.',
      quote_plan:
        'Get the SAME authoritative USD retail total and KES payment amount as checkout, including saved markups and a supplied promo code. Requires explicit travel dates and quantity from customer. Does not buy or reserve anything. Never make up dates, codes or quantity.',
      list_my_esims:
        "List only the authenticated customer's eSIMs and masked identifiers. offset starts at 0. Never accepts an email or other user ID.",
      list_my_orders:
        "List only the authenticated customer's purchases and payment status, 12 per page; offset starts at 0.",
      my_esim_details:
        "Read an owned eSIM's usage, device, status history or eligible same-destination fixed top-up plans. Get esimId from list_my_esims. Cannot purchase, top up, change dates or reveal installation codes.",
      help: 'Get verified website support guidance and a link. No promises about refunds, network speeds, compatible devices or payment success beyond these facts.',
    } as Record<string, string>
  )[name],
  parameters: z.toJSONSchema(schema, { target: 'draft-7' }),
}));
const money = (n: number) => `USD ${n.toFixed(2)}`;
const iso = (d: Date | null | undefined) => d?.toISOString() ?? null;
const helpCard = (title: string, href = '/help'): AssistantCard => ({
  title,
  lines: [],
  href,
  label: 'Open page',
  kind: 'help',
});

@Injectable()
export class AssistantToolsService {
  constructor(
    private readonly catalog: CatalogService,
    private readonly payments: PaymentsService,
    private readonly prisma: PrismaService,
    private readonly usage: UsageService,
  ) {}

  async run(
    name: string,
    input: unknown,
    userId?: string,
  ): Promise<ToolResult> {
    const schema = args[name as keyof typeof args];
    if (!schema)
      return {
        data: { error: 'Tool is not available. No action was taken.' },
        cards: [],
      };
    if (!schema.safeParse(input).success)
      return {
        data: {
          error:
            'Invalid tool arguments. Ask for the missing or correct details.',
        },
        cards: [],
      };
    if (
      ['list_my_esims', 'list_my_orders', 'my_esim_details'].includes(name) &&
      !userId
    ) {
      return {
        data: {
          error:
            'Sign in on the website to view your own account. Never send login codes in chat.',
        },
        cards: [
          helpCard('Sign in to your account', '/login?next=%2Faccount%2Fesims'),
        ],
      };
    }
    try {
      if (['search_destinations', 'list_plans', 'quote_plan'].includes(name))
        await this.catalog.ensureFresh();
      switch (name) {
        case 'search_destinations': {
          const { query } = args.search_destinations.parse(input);
          if (!this.catalog.availability.available) return this.unavailable();
          const results = this.catalog
            .search(query, 12)
            .map((c) => ({ code: c.iso, name: c.name, region: c.region }));
          return { data: { destinations: results }, cards: [] };
        }
        case 'list_plans': {
          const a = args.list_plans.parse(input);
          if (!this.catalog.availability.available) return this.unavailable();
          const direct = this.catalog.getCountry(a.destination);
          const matches = direct
            ? [direct]
            : this.catalog.search(a.destination, 12);
          if (matches.length !== 1)
            return {
              data: {
                destinations: matches.map((c) => ({
                  code: c.iso,
                  name: c.name,
                })),
                message:
                  'Choose one matching destination before listing plans.',
              },
              cards: [],
            };
          return this.plans(matches[0].iso, a.offset);
        }
        case 'quote_plan': {
          const a = args.quote_plan.parse(input);
          const p = this.catalog.getProduct(a.productId);
          if (!p)
            return {
              data: { error: 'Plan no longer available. Search again.' },
              cards: [],
            };
          // Exactly the checkout pricing service, including current store markups and FX.
          const q = await this.payments.quote(
            { ...a, promoCode: a.promoCode ?? undefined },
            userId,
          );
          const quotedAt = new Date().toISOString();
          return {
            data: {
              ...q,
              title: p.title,
              quotedAt,
              notice:
                'Not a reservation. Checkout requotes and asks you to confirm any price change.',
            },
            cards: [
              {
                kind: 'quote',
                title: p.title,
                href: `/plan/${encodeURIComponent(p.id)}`,
                label: 'Review dates and price at checkout',
                lines: [
                  `${q.startDate} to ${q.endDate} · ${q.days} days · ${q.quantity} eSIM(s)`,
                  `Trip total: ${money(q.total)}`,
                  `Discount included: ${money(q.discount)}`,
                  q.chargeAmount === null
                    ? 'KES conversion unavailable — payments paused.'
                    : `Payment amount: KES ${q.chargeAmount.toFixed(2)}`,
                  ...(q.checkoutNotice ? [q.checkoutNotice] : []),
                  `Quoted ${quotedAt}. Reconfirmed at checkout.`,
                ],
              },
            ],
          };
        }
        case 'list_my_esims': {
          const { offset: skip } = args.list_my_esims.parse(input);
          const rows = await this.prisma.esim.findMany({
            where: { userId: userId! },
            orderBy: [{ createdAt: 'desc' }, { id: 'asc' }],
            skip,
            take: 13,
            select: {
              id: true,
              iccid: true,
              profileStatus: true,
              unlimited: true,
              expiresAt: true,
              usageUpdatedAt: true,
              order: { select: { title: true, destinationIso: true } },
            },
          });
          const esims = rows.slice(0, 12).map((e) => ({
            id: e.id,
            iccidLast4: e.iccid.slice(-4),
            title: e.order.title,
            destination: e.order.destinationIso,
            status: e.profileStatus,
            unlimited: e.unlimited,
            expiresAt: iso(e.expiresAt),
            usageUpdatedAt: iso(e.usageUpdatedAt),
          }));
          return {
            data: { esims, nextOffset: rows.length > 12 ? skip + 12 : null },
            cards: esims.map((e) => ({
              kind: 'account',
              title: e.title,
              lines: [`eSIM ending ${e.iccidLast4}`, `Status: ${e.status}`],
              href: `/account/esims#esim-${encodeURIComponent(e.id)}`,
              label: 'View eSIM / top up',
            })),
          };
        }
        case 'list_my_orders': {
          const { offset: skip } = args.list_my_orders.parse(input);
          const rows = await this.prisma.order.findMany({
            where: { userId: userId! },
            orderBy: [{ createdAt: 'desc' }, { id: 'asc' }],
            skip,
            take: 13,
            select: {
              id: true,
              title: true,
              kind: true,
              status: true,
              totalKes: true,
              currency: true,
              quantity: true,
              createdAt: true,
              payment: { select: { state: true } },
            },
          });
          const orders = rows.slice(0, 12).map((o) => ({
            id: o.id,
            title: o.title,
            kind: o.kind,
            status: o.status,
            total: Number(o.totalKes),
            currency: o.currency,
            quantity: o.quantity,
            createdAt: iso(o.createdAt),
            paymentStatus: o.payment?.state ?? null,
          }));
          return {
            data: { orders, nextOffset: rows.length > 12 ? skip + 12 : null },
            cards: orders.map((o) => ({
              kind: 'account',
              title: o.title,
              lines: [
                `${o.currency} ${o.total.toFixed(2)} · ${o.status}`,
                `Payment: ${o.paymentStatus ?? 'Not started'}`,
              ],
              href: `/order/${encodeURIComponent(o.id)}`,
              label: 'View order',
            })),
          };
        }
        case 'my_esim_details': {
          const a = args.my_esim_details.parse(input);
          // Authorization BEFORE supplier reads, even for ADMINs. No email/ICCID lookup.
          const owned = await this.prisma.esim.findFirst({
            where: { id: a.esimId, userId: userId! },
            select: { id: true, order: { select: { destinationIso: true } } },
          });
          if (!owned)
            return {
              data: { error: 'eSIM not found in your account.' },
              cards: [],
            };
          const card: AssistantCard = {
            kind: 'account',
            title: 'Your eSIM',
            lines: [],
            href: `/account/esims#esim-${encodeURIComponent(owned.id)}`,
            label: 'View details / top up',
          };
          if (a.detail === 'topup_plans')
            return this.plans(owned.order.destinationIso, 0, card);
          if (a.detail === 'device') {
            const d = await this.usage.getDevice(owned.id, userId);
            return {
              data: {
                device: d
                  ? {
                      brand: d.oem,
                      model: d.hardwareModel,
                      name: d.hardwareName,
                    }
                  : null,
              },
              cards: [card],
            };
          }
          if (a.detail === 'history') {
            const history = (await this.usage.getHistory(owned.id, userId))
              .slice(-20)
              .map((h) => ({ status: h.status, date: h.statusDate }));
            return { data: { history }, cards: [card] };
          }
          const usage = await this.usage.getUsage(owned.id, userId);
          const stamp = await this.prisma.esim.findFirst({
            where: { id: owned.id, userId: userId! },
            select: { usageUpdatedAt: true },
          });
          return {
            data: {
              usage,
              lastConfirmedAt: iso(stamp?.usageUpdatedAt),
              note: 'Last confirmed usage may lag the network. Unlimited does not imply no fair-use limits.',
            },
            cards: [card],
          };
        }
        case 'help': {
          const { topic } = args.help.parse(input);
          const help = {
            installation: {
              message:
                'Install over Wi-Fi using the secure QR/manual details in My eSIMs. Select the travel eSIM for mobile data and follow its roaming instructions. Do not delete the eSIM while troubleshooting.',
              href: '/how-it-works',
            },
            compatibility: {
              message:
                'Check the exact device model and carrier-unlocked status before purchase. Do not assume all phones with the same brand support eSIM.',
              href: '/compatibility',
            },
            payments: {
              message:
                'Checkout offers card and mobile money, subject to provider availability. Store prices are USD; review the exact KES charge before payment. Never share card numbers, PINs or login codes in chat. The server must verify payment status.',
              href: '/help',
            },
            refunds: {
              message:
                'Support must review refund eligibility. The assistant cannot approve or issue a refund.',
              href: '/legal/refunds',
            },
            support: {
              message:
                'Contact support for delivery issues, incorrect travel dates or failed activation. Never send your QR/activation code or login code in chat.',
              href: '/help',
            },
            privacy: {
              message:
                "AI chat sends your messages and limited relevant catalogue or own-account summaries to OpenAI. Account access requires website login. Installation codes, payment credentials and supplier credentials are not sent by these tools. Clear chat removes this browser session's conversation.",
              href: '/legal/privacy',
            },
          }[topic];
          return { data: help, cards: [helpCard(topic, help.href)] };
        }
      }
    } catch (error) {
      // Never pass raw supplier/database errors or credentials to the model/browser.
      const status =
        typeof (error as { getStatus?: unknown }).getStatus === 'function'
          ? (error as { getStatus(): number }).getStatus()
          : 500;
      return {
        data: {
          error:
            status === 400
              ? 'The dates, duration, quantity or promo code are invalid. Check them in checkout.'
              : 'The requested information is temporarily unavailable. No purchase or account change was made.',
        },
        cards: [helpCard('Get help')],
      };
    }
    return { data: { error: 'Tool unavailable.' }, cards: [] };
  }

  private unavailable(): ToolResult {
    return {
      data: {
        error:
          'Catalogue temporarily unavailable. Do not infer a destination is not covered.',
      },
      cards: [helpCard('Browse later', '/destinations')],
    };
  }

  private plans(
    destination: string,
    skip: number,
    topupCard?: AssistantCard,
  ): ToolResult {
    const all = this.catalog
      .listProducts(destination)
      .filter((p) => !topupCard || !p.unlimited);
    const plans = all.slice(skip, skip + 12).map((p) => ({
      productId: p.id,
      destination: p.destName,
      title: p.title,
      data: p.dataLabel,
      minDays: p.minDays,
      maxDays: p.validityDays,
      unlimited: p.unlimited,
      estimatedRetailUsd: p.priceKes,
      basis: p.unlimited ? 'PER_DAY_ESTIMATE' : 'PACKAGE_ESTIMATE',
    }));
    return {
      data: {
        plans,
        nextOffset: all.length > skip + 12 ? skip + 12 : null,
        notice:
          'Catalogue estimates only. Use quote_plan for the exact dated total, quantity, discounts and payment currency.',
      },
      cards: plans.map((p) => ({
        kind: 'plan',
        title: p.title,
        lines: [
          `${p.minDays}–${p.maxDays} travel days`,
          `Estimate: ${money(p.estimatedRetailUsd)}${p.unlimited ? ' per day' : ' per eSIM'}`,
          'Select travel dates for an exact quote.',
        ],
        href: topupCard?.href ?? `/plan/${encodeURIComponent(p.productId)}`,
        label: topupCard ? 'Choose top-up in My eSIMs' : 'Review this plan',
      })),
    };
  }
}
